def removals(arr, k):
    amax, amin = max(arr), min(arr)
    if amax - amin <= k:
        return 0
    arr.sort()
    left, right = 0, len(arr) - 1
    while left < right:
        if arr[right] - arr[left] <= k:
            break
        right -= 1
    return len(arr) - right - 1

