def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

class Sum:
    """Class to calculate the sum of prime divisors."""
    def __init__(self, num):
        self.num = num
        self.prime_divisors = self.find_prime_divisors()

    def find_prime_divisors(self):
        """Find all prime divisors of the number."""
        divisors = set()
        for i in range(2, self.num + 1):
            if self.num % i == 0 and is_prime(i):
                divisors.add(i)
        return divisors

    def __call__(self):
        """Return the sum of prime divisors."""
        return sum(self.prime_divisors)

