    if len(s) % 2 != 0:
        return False  # If the length is odd, it cannot be made up of two alternating characters

    # Initialize two variables to store the count of characters at each position in the string
    char_count = {}

    # Iterate over each character in the string
    for char in s:
        # If the character is already in the dictionary, increment its count
        if char in char_count:
            char_count[char] += 1
        # If the character is not in the dictionary, add it with a count of 1
        else:
            char_count[char] = 1

    # If the string has more than two distinct characters, it cannot be made up of two alternating characters
    if len(char_count) > 2:
        return False

    # If the string has exactly two distinct characters, check if the counts of each character are either 
    # 0, n/2 or n where n is the length of the string
    if len(char_count) == 2:
